#!/usr/bin/env python3
"""Turns FSRCNNX's mpv shader into plain fragment shaders. Run before gen.sh when the model changes."""
import pathlib
import re

here = pathlib.Path(__file__).parent
src = (here / "../../../third_party/fsrcnnx/FSRCNNX_x2_8-0-4-1.glsl").read_text()
passes = re.split(r"(?=^//!HOOK )", src, flags=re.M)[1:]
HEADER = """#version 450
// Generated by gen_fsrcnnx.py from FSRCNNX (LGPL 3, see third_party/fsrcnnx).
#extension GL_EXT_samplerless_texture_functions : require
#define FETCH(t, o) texelFetch(t, clamp(ivec2(gl_FragCoord.xy) + ivec2(o), ivec2(0), textureSize(t, 0) - 1), 0)
layout(location = 0) out vec4 frag;
"""
for f in here.glob("fsrcnnx_[0-9]*.frag.glsl"):
    f.unlink()
# The last pass only unpacks channels into pixels, so it is written by hand: see fsrcnnx_unpack.
for i, text in enumerate(passes[:-1]):
    binds = re.findall(r"^//!BIND (\w+)$", text, flags=re.M)
    saved = re.search(r"^//!SAVE (\w+)$", text, flags=re.M).group(1)
    out = HEADER
    for b, name in enumerate(binds):
        out += f"layout(set = 1, binding = {b}) uniform texture2D {name};\n"
        if name == "LUMA":
            out += "#define LUMA_texOff(o) vec4(dot(FETCH(LUMA, o).rgb, vec3(0.2126, 0.7152, 0.0722)))\n"
        else:
            out += f"#define {name}_texOff(o) FETCH({name}, o)\n"
    out += text[text.index("vec4 hook()"):] + "void main() { frag = hook(); }\n"
    (here / f"fsrcnnx_{i}.frag.glsl").write_text(out)
    print(i, binds, "->", saved)
